node -e "
const Ajv8 = require('./node_modules/ajv').default || require('./node_modules/ajv');
const Ajv6 = require('./node_modules/eslint/node_modules/ajv');

for (const [label, Ctor] of [['ajv8', Ajv8], ['ajv6', Ajv6]]) {
  const opts = '_addVocabularies' in Ctor.prototype
    ? {allErrors: true, strict: false, validateFormats: false}
    : {allErrors: true, format: false, jsonPointers: true};
  const ajv = new Ctor(opts);
  // 1. Valid format + unknown keyword
  const v1 = ajv.compile({
    type: 'object',
    properties: {when: {type: 'string', format: 'date-time', 'x-ui': 'picker'}},
  });
  console.log(label, 'format+x-ui valid:', v1({when: 'not-a-date'}));

  // 2. Invalid schema throws at compile time
  let threw = false;
  try {
    ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
  } catch (e) {
    threw = true;
  }
  console.log(label, 'invalid schema throws:', threw);
}
"

